export function getBlogPostHi(slug: string) {
  return blogPostsHi.find((p) => p.slug === slug);
}

export function getRelatedPostsHi(slug: string, count = 3) {
  return blogPostsHi.filter((p) => p.slug !== slug).slice(0, count);
}
